if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}csrf_check();$id=(int)($_POST['id']??0);$s=$pdo->prepare('SELECT * FROM eco_editable_offers WHERE id=?');$s->execute([$id]);$original=$s->fetch(PDO::FETCH_ASSOC);if(!$original){http_response_code(404);exit('Oferta nu există.');}
